sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_safeRender;
uniform float amzp_completion;
uniform float amzp_shards;
uniform float amzp_rings;
uniform float amzp_rnd;
uniform float2 amzp_center;
uniform float amzp_crackW;
uniform float amzp_crackGrow;
uniform float amzp_crackFill;
layout(color) uniform half4 amzp_crackCol;
uniform float amzp_edgeGrain;
uniform float amzp_grainW;
uniform float amzp_grainAll;
uniform float amzp_grainSize;
uniform float amzp_grainDir;
uniform float amzp_grainAnim;
uniform float amzp_spread;
uniform float amzp_rotRand;
uniform float amzp_fall;
uniform float amzp_stagger;
uniform float amzp_shardFade;
uniform float amzp_shardShade;
uniform float amzp_seed;
uniform float amzp_overdrawOn;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float3 h33(float2 p) {
        float3 q = fract(float3(p.xyx) * float3(0.1031, 0.1030, 0.0973) + amzp_seed * 0.0173);
        q += dot(q, q.yxz + 33.33);
        return fract((q.xxy + q.yzz) * q.zyx);
    }
    float h1(float n) { return fract(sin(n * 12.9898 + amzp_seed * 78.233) * 43758.5453123); }
    float2 W; float2 CT; float RR; float NS; float NR; float CMP; float VMIN; float DV; float PA;
    float2 sd[15]; float2 sdC[15]; float2 sid[15]; float sok[15];
    float2 SO[15]; float SA[15]; float SC[15];
    float ringOff(float j) { return h1(j * 7.31 + 1.7); }
    float2 seedLP(float i, float j) {
        float iw = mod(i, NS);
        float3 h = h33(float2(iw, j) + 0.37);
        float u = (i + 0.5 + (h.x - 0.5) * amzp_rnd * 0.8 + ringOff(j)) / NS * 6.28318531;
        float v = VMIN + (j + 0.5 + (h.y - 0.5) * amzp_rnd * 0.8) * DV;
        return float2(u, v);
    }
    void buildSeeds(float2 p) {
        float2 d = p - CT;
        float r = max(length(d), 0.5);
        PA = atan(d.y, d.x);
        float v = log(r);
        float j0 = floor((v - VMIN) / DV);
        j0 = clamp(j0, 1.0, NR + 1.0);
        for (int jj = 0; jj < 3; jj++) {
            float j = j0 + float(jj) - 1.0;
            float ai = PA / 6.28318531 * NS - ringOff(j) - 0.5;
            float i0 = floor(ai + 0.5);
            for (int ii = 0; ii < 5; ii++) {
                float i = i0 + float(ii) - 2.0;
                float2 s = seedLP(i, j);
                float2 sc = CT + exp(s.y) * float2(cos(s.x), sin(s.x));
                sd[jj * 5 + ii] = s; sdC[jj * 5 + ii] = sc;
                sid[jj * 5 + ii] = float2(mod(i, NS), j);
                sok[jj * 5 + ii] = (j >= 0.0 && j <= NR + 2.0) ? 1.0 : 0.0;
                float3 h = h33(float2(mod(i, NS), j) + 11.3);
                float st = clamp(amzp_stagger, 0.0, 1.0) * 0.45;
                float c = clamp((CMP - 0.15 - h.z * st) / max(0.85 - st, 0.05), 0.0, 1.0);
                float2 dir = sc - CT;
                dir = length(dir) > 1.0 ? normalize(dir) : normalize(h.xy - 0.5 + 1e-4);
                float2 o = dir * amzp_spread * pxs() * pow(c, 1.3) * (0.5 + h.x);
                o.y -= amzp_fall * pxs() * c * c;
                SO[jj * 5 + ii] = o;
                SA[jj * 5 + ii] = (h.y - 0.5) * 2.0 * radians(amzp_rotRand) * c;
                SC[jj * 5 + ii] = c;
            }
        }
    }
    float2 toLP(float2 q) {
        float2 d = q - CT;
        float2 dp = float2(cos(PA), sin(PA));
        float da = atan(dp.x * d.y - dp.y * d.x, dot(dp, d));
        return float2(PA + da, log(max(length(d), 0.5)));
    }
    int KB; float2 QB; float DB;
    void findShard(float2 p) {
        KB = -1; DB = -1e9; QB = p;
        for (int k = 0; k < 15; k++) {
            if (sok[k] < 0.5) continue;
            float2 skC = sdC[k];
            float2 q = advRot(p - skC - SO[k], -SA[k]) + skC;
            float2 ql = toLP(q);
            float2 sk = sd[k];
            float mx = -1e9;
            for (int m = 0; m < 15; m++) {
                if (m == k || sok[m] < 0.5) continue;
                float2 sm = sd[m];
                float2 dv = sm - sk;
                float l = length(dv);
                if (l < 1e-4) continue;
                mx = max(mx, dot(ql - 0.5 * (sk + sm), dv / l));
            }
            float bd = -mx * exp(ql.y);
            if (bd > DB) { DB = bd; KB = k; QB = q; }
        }
    }
    float2 grainVec(float2 p, float gs, float salt) {
        float fr = (amzp_grainAnim>0.5) ? floor(time * 30.0) : 0.0;
        float3 h = h33(floor(p / max(gs, 0.5)) + float2(fr * 1.31 + salt, fr * 0.73));
        float2 g = (h.xy - 0.5) * 2.0;
        if (int(amzp_grainDir) == 1) g.y = 0.0;
        else if (int(amzp_grainDir) == 2) g.x = 0.0;
        return g;
    }
    void amzRender() {
        if ((amzp_safeRender>0.5)) { amzOutput = amzTexture(0, amzScreenNorm()); return; }
        W = layer;
        float2 uv = amzLayerNorm();
        float ps = pxs();
        CT = (float2(0.5) + float2(amzp_center.x, -amzp_center.y) * ps / W) * W;
        RR = 0.5 * length(W) + length(CT - 0.5 * W);
        NS = max(floor(amzp_shards + 0.5), 1.0);
        NR = max(floor(amzp_rings + 0.5), 1.0);
        VMIN = log(max(0.03 * RR, 1.0));
        DV = (log(max(RR, 2.0)) - VMIN) / NR;
        CMP = clamp(amzp_completion, 0.0, 1.0);
        float2 p = uv * W;
        if (amzp_grainAll > 0.0) p += grainVec(p, amzp_grainSize * ps, 3.0) * amzp_grainAll * ps;
        float4 R;
        if (CMP <= 0.0) {
            R = layerAt(p / W);
        } else {
            buildSeeds(p);
            findShard(p);
            float ch = 0.5 * amzp_crackW * ps * smoothstep(0.0, 0.15, CMP) + amzp_crackGrow * ps * smoothstep(0.1, 1.0, CMP);
            ch *= mix(0.35, 1.0, smoothstep(0.0, 0.25 * RR, length(p - CT)));
            float gw = amzp_grainW * ps;
            if (amzp_edgeGrain > 0.0 && KB >= 0 && DB < ch + gw) {
                float f = 1.0 - clamp((DB - ch) / max(gw, 0.001), 0.0, 1.0);
                float2 pj = p + grainVec(p, amzp_grainSize * ps, 9.0) * amzp_edgeGrain * ps * f;
                findShard(pj);
            }
            float4 fillC = int(amzp_crackFill) == 1 ? float4(amzp_crackCol.rgb, 1.0) * layerAt(p / W).a : float4(0.0);
            if (KB < 0 || DB < ch) {
                R = fillC;
            } else {
                float4 c = layerAt(QB / W);
                float sc = 1.0, cc = 0.0;
                float2 idv = float2(0.0);
                for (int k = 0; k < 15; k++) { if (k == KB) { idv = sid[k]; cc = SC[k]; } }
                float3 h = h33(idv + 5.1);
                c.rgb *= 1.0 + (h.x - 0.5) * 2.0 * amzp_shardShade;
                c = float4(min(c.rgb, float3(c.a)), c.a);
                c *= 1.0 - amzp_shardFade * cc;
                float aa = clamp((DB - ch) / 1.0, 0.0, 1.0);
                R = mix(fillC, c, aa);
                if (int(amzp_crackFill) == 0) R = c * aa;
            }
        }
        amzOutput = R;
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
